const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI personal finance advisor for Mana Community residents. You analyze monthly household ledger entries across categories (society maintenance, groceries, electricity, club dining, child activities). Detect unusual budget drift vs 3-month trailing baselines and generate proactive money-saving strategies.

Analyze the input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{
  "householdId": "FLAT-B-402",
  "monthlyTotalExpense": 64800,
  "trailingThreeMonthAverage": 52300,
  "budgetDriftPercentage": 23.9,
  "driftSeverity": "MODERATE_SURGE",
  "highestSurgeCategories": [
    { "category": "Community Dining & Home Chefs", "currentSpend": 18400, "averageSpend": 11200, "surgePct": 64.3 },
    { "category": "Electricity & Air-Conditioning", "currentSpend": 9200, "averageSpend": 6400, "surgePct": 43.8 }
  ],
  "actionableTips": [
    "Take advantage of Society Group Buying monthly pantry baskets to save up to 18% on staple groceries",
    "Switch EV charging to off-peak night tariff window (23:00 - 06:00) to cut charging costs by 35%"
  ]
}

Rules:
- driftSeverity must be one of: "WITHIN_BUDGET", "MINOR_VARIANCE", "MODERATE_SURGE", "CRITICAL_OVERSPEND".
- Return pure JSON only, no markdown wrapping.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"householdId":"FLAT-B-402","monthlyTotalExpense":64800,"trailingThreeMonthAverage":52300,"budgetDriftPercentage":23.9,"driftSeverity":"MODERATE_SURGE","highestSurgeCategories":[{"category":"Community Dining & Home Chefs","currentSpend":18400,"averageSpend":11200,"surgePct":64.3},{"category":"Electricity & Air-Conditioning","currentSpend":9200,"averageSpend":6400,"surgePct":43.8}],"actionableTips":["Take advantage of Society Group Buying monthly pantry baskets to save up to 18% on staple groceries","Switch EV charging to off-peak night tariff window (23:00 - 06:00) to cut charging costs by 35%"]} } }];
}
